import { useState, useEffect } from "react";
import { invoke } from "@tauri-apps/api/core";
import { Stack } from "@/shared/ui/layout/Stack";
import { Grid } from "@/shared/ui/layout/Grid";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { TextArea } from "@/shared/ui/controls/Field";
import { Button } from "@/shared/ui/controls/Button";
import { Code } from "@/shared/ui/data/Code";

// A single component with 5 simultaneous first-party sibling cross-imports reliably fails to build
// in this sandbox ("resolving to no kit component") even though each of the 5 resolves fine on its
// own elsewhere — filed as request #56. Inlined the 5 sub-pieces' already-verified bodies as local
// (non-exported) functions instead, same pattern as AgentRolesCard's local RoleRow.

// TargetSelector — inlined verbatim from the promoted `targetselector` component.
function TargetSelector({ allRepos, target, setTarget }) {
  return (
    <Stack gap={6}>
      <Box className="mono-label">target</Box>
      <Row gap={6} align="stretch" wrap>
        {["global", ...allRepos.map((r) => r.local_path)].map((t) => {
          const isGlobal = t === "global";
          const label = isGlobal ? "global (~/.claude/)" : (allRepos.find((r) => r.local_path === t)?.full_name ?? t);
          const on = target === t;
          return (
            <Box
              key={t}
              className="mono"
              onClick={() => setTarget(t)}
              pad={[5, 12]} bg={on ? "var(--accent)" : "var(--bg-elev)"} radius={6} style={{ cursor: "pointer",
                fontSize: 11,
                color: on ? "var(--on-accent)" : "var(--fg-muted)",
                border: "1px solid " + (on ? "transparent" : "var(--border-soft)"),
                fontWeight: on ? 600 : 400,
              }}
            >{label}</Box>
          );
        })}
      </Row>
      {allRepos.length === 0 && (
        <Box className="mono-caption">Resolve repositories on the Projects board to unlock per-repo targets.</Box>
      )}
    </Stack>
  );
}

// ProfileBar — inlined verbatim from the promoted `profilebar` component.
function ProfileBar({
  configProfiles, activeProfileId, setActiveProfileId, loadProfile,
  showSaveDialog, setShowSaveDialog, newProfileName, setNewProfileName,
  handleSaveProfile, removeConfigProfile, targetLabel,
}) {
  return (
    <Row gap={10} style={{
      padding: "10px 14px",
      background: "var(--bg-panel)", border: "1px solid var(--border-soft)", borderRadius: 8,
    }}>
      <Box as="span" className="mono-label">profile</Box>
      <select
        value={activeProfileId ?? ""}
        onChange={(e) => {
          const p = configProfiles.find((x) => x.id === e.target.value);
          if (p) loadProfile(p);
          else setActiveProfileId(null);
        }}
        className="mono"
        style={{
          background: "var(--bg-canvas)", border: "1px solid var(--border-soft)",
          borderRadius: 4, padding: "3px 8px",
          fontSize: 11, color: "var(--fg)",
        }}
      >
        <option value="">{"— custom / unsaved —"}</option>
        {configProfiles.map((p) => (
          <option key={p.id} value={p.id}>{p.name}</option>
        ))}
      </select>

      {!showSaveDialog ? (
        <Button
          variant="ghost"
          style={{ height: 26, fontSize: 10.5 }}
          onClick={() => {
            setNewProfileName(configProfiles.find((p) => p.id === activeProfileId)?.name ?? "");
            setShowSaveDialog(true);
          }}
        >{activeProfileId ? "update profile" : "save as profile…"}</Button>
      ) : (
        <Row gap={6}>
          <input
            className="input mono"
            autoFocus
            value={newProfileName}
            onChange={(e) => setNewProfileName(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") handleSaveProfile(); if (e.key === "Escape") setShowSaveDialog(false); }}
            placeholder="profile name…"
            style={{ width: 160, height: 26, fontSize: 10.5 }}
          />
          <Button variant="primary" style={{ height: 26, fontSize: 10.5 }} onClick={handleSaveProfile}>save</Button>
          <Button variant="ghost" style={{ height: 26, fontSize: 10.5 }} onClick={() => setShowSaveDialog(false)}>cancel</Button>
        </Row>
      )}

      {activeProfileId && (
        <Button
          variant="ghost"
          style={{ height: 26, fontSize: 10.5, color: "var(--danger)", marginLeft: 2 }}
          onClick={() => { removeConfigProfile(activeProfileId); setActiveProfileId(null); }}
        >delete</Button>
      )}

      <Spacer />
      <Box as="span" className="mono-caption">{targetLabel}</Box>
    </Row>
  );
}

// ClaudeMdEditor — inlined verbatim from the promoted `claudemdeditor` component.
function ClaudeMdEditor({ instructions, setInstructions, setActiveProfileId, reading, targetLabel }) {
  return (
    <Stack gap={10}>
      <Box bg="var(--bg-panel)" border="soft" radius={8} style={{ overflow: "hidden" }}>
        <Row className="mono" gap={8} style={{
          padding: "8px 14px", borderBottom: "1px solid var(--border-soft)",
          background: "var(--bg-elev)",
          fontSize: 10,
        }}>
          <Text as="span" tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".06em" }}>CLAUDE.md</Text>
          {reading && <Text as="span" tone="dim">loading…</Text>}
          <Spacer />
          <Text as="span" tone="dim">{targetLabel}</Text>
        </Row>
        <TextArea
          className="mono"
          value={instructions}
          onChange={(v) => { setInstructions(v); setActiveProfileId(null); }}
          placeholder="# Instructions&#10;&#10;Write system-level instructions for Claude in this scope…"
          style={{
            width: "100%", minHeight: 220,
            background: "var(--bg-canvas)", border: "none", outline: "none",
            borderRadius: 0,
            padding: "14px 16px",
            fontSize: 11.5, color: "var(--fg)",
            resize: "vertical", lineHeight: 1.65,
            boxSizing: "border-box",
          }}
        />
      </Box>
    </Stack>
  );
}

// ToolPermissionsPanel — inlined verbatim from the promoted `toolpermissionspanel` component.
const TOOL_PRESETS = [
  { label: "read-only", allow: ["Read", "Glob", "Grep"], deny: ["Write", "Edit", "MultiEdit", "Bash", "WebFetch", "WebSearch"] },
  { label: "no-bash", allow: [], deny: ["Bash"] },
  { label: "no-web", allow: [], deny: ["WebFetch", "WebSearch"] },
  { label: "full", allow: [], deny: [] },
];
const COMMON_TOOLS = ["Read", "Write", "Edit", "MultiEdit", "Bash", "Glob", "Grep", "WebFetch", "WebSearch"];
function ToolChip({ label, onRemove }) {
  return (
    <Box as="span" className="mono" pad={[2, 8]} bg="var(--bg-elev)" border="soft" radius={4} style={{
      display: "inline-flex", alignItems: "center", gap: 4,
      fontSize: 10.5, color: "var(--fg-muted)",
    }}>
      {label}
      <Text as="span" tone="dim" onClick={onRemove} style={{ cursor: "pointer", lineHeight: 1 }}>×</Text>
    </Box>
  );
}
function ChipInput({ value, onChange, onAdd, placeholder }) {
  return (
    <Row gap={5}>
      {/* eslint-disable-next-line no-restricted-syntax -- bespoke inline datalist-backed entry (fixed width/height) beside a custom "+ add"; a TextField .field wrapper would break the Row */}
      <input
        className="input mono"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); onAdd(); } }}
        placeholder={placeholder}
        list="tool-suggestions"
        style={{ width: 130, height: 24, padding: "0 8px", fontSize: 10.5 }}
      />
      <datalist id="tool-suggestions">
        {COMMON_TOOLS.map((t) => <option key={t} value={t} />)}
      </datalist>
      <Box as="span" className="mono" onClick={onAdd} pad={[2, 8]} bg="var(--bg-elev)" border="soft" radius={4} style={{ cursor: "pointer",
        fontSize: 10.5, color: "var(--fg-muted)",
      }}>+ add</Box>
    </Row>
  );
}
function ToolPermissionsPanel({ allow, setAllow, deny, setDeny, allowInput, setAllowInput, denyInput, setDenyInput, applyPreset, addToAllow, addToDeny }) {
  return (
    <Box bg="var(--bg-panel)" border="soft" radius={8} style={{ overflow: "hidden" }}>
      <Box className="mono" pad={[8, 14]} bg="var(--bg-elev)" style={{ borderBottom: "1px solid var(--border-soft)",
        fontSize: 10,
        color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".06em",
      }}>
        Tool permissions
      </Box>
      <Stack gap={16} style={{ padding: "14px 14px" }}>
        <Box>
          <Text as="div" mono size={9.5} tone="dim" style={{ marginBottom: 7, textTransform: "uppercase", letterSpacing: ".06em" }}>quick presets</Text>
          <Row gap={5} align="stretch" wrap>
            {TOOL_PRESETS.map((p) => (
              <Box
                as="span"
                key={p.label}
                className="mono"
                onClick={() => applyPreset(p)}
                pad={[2, 8]} bg="var(--bg-elev)" border="soft" radius={4} style={{ cursor: "pointer",
                  fontSize: 10,
                  color: "var(--fg-muted)",
                }}
              >{p.label}</Box>
            ))}
          </Row>
        </Box>

        <Box>
          <Text as="div" mono size={9.5} tone="success" style={{ marginBottom: 7, textTransform: "uppercase", letterSpacing: ".06em" }}>allow</Text>
          <Row gap={5} align="stretch" wrap style={{ marginBottom: 8 }}>
            {allow.length === 0 && (
              <Text as="span" mono size={10.5} tone="dim" style={{ fontStyle: "italic" }}>all tools allowed</Text>
            )}
            {allow.map((t) => (
              <ToolChip key={t} label={t} onRemove={() => setAllow((a) => a.filter((x) => x !== t))} />
            ))}
          </Row>
          <ChipInput value={allowInput} onChange={setAllowInput} onAdd={addToAllow} placeholder="tool name..." />
        </Box>

        <Box>
          <Text as="div" mono size={9.5} tone="danger" style={{ marginBottom: 7, textTransform: "uppercase", letterSpacing: ".06em" }}>deny</Text>
          <Row gap={5} align="stretch" wrap style={{ marginBottom: 8 }}>
            {deny.length === 0 && (
              <Text as="span" mono size={10.5} tone="dim" style={{ fontStyle: "italic" }}>nothing denied</Text>
            )}
            {deny.map((t) => (
              <ToolChip key={t} label={t} onRemove={() => setDeny((d) => d.filter((x) => x !== t))} />
            ))}
          </Row>
          <ChipInput value={denyInput} onChange={setDenyInput} onAdd={addToDeny} placeholder="tool name..." />
        </Box>

        {(allow.length > 0 || deny.length > 0) && (
          <Code wrap={false} tone="dim" style={{ fontSize: 9.5, padding: "10px 12px", borderRadius: 6 }}>
            {JSON.stringify({ permissions: { allow, deny } }, null, 2)}
          </Code>
        )}
      </Stack>
    </Box>
  );
}

// WriteBar — inlined verbatim from the promoted `writebar` component.
function WriteBar({ writeStatus, writeMsg, reading, writing, setReadTick, handleWrite }) {
  return (
    <Row gap={10} style={{
      padding: "10px 14px",
      background: "var(--bg-panel)", border: "1px solid var(--border-soft)", borderRadius: 8,
    }}>
      {writeStatus === "ok" && <Text as="span" mono size={11} tone="success">✓ {writeMsg}</Text>}
      {writeStatus === "error" && <Text as="span" mono size={11} tone="danger">{writeMsg}</Text>}
      {writeStatus === "idle" && <Text as="span" mono size={11} tone="dim">CLAUDE.md and .claude/settings.json</Text>}
      <Spacer />
      <Button variant="ghost" style={{ height: 28, fontSize: 11 }} disabled={reading} onClick={() => setReadTick((n) => n + 1)}>
        {reading ? "reading…" : "↺ read from disk"}
      </Button>
      <Button variant="primary" style={{ height: 28, fontSize: 11 }} disabled={writing || reading} onClick={handleWrite}>
        {writing ? "writing…" : "↓ write to disk"}
      </Button>
    </Row>
  );
}

// Preview-only stand-in for `deriveAllRepos(projectLocalRepos, bscBaseDir)` (./claudeConfig.helpers)
// — the real derivation reads the app store; same output SHAPE, fixed sample data.
const SAMPLE_REPOS = [
  { full_name: "kevin/base-studio-code", local_path: "C:/Users/Kevin/.base-studio-code/projects/base-studio-code/base-studio-code" },
  { full_name: "kevin/northwind-api", local_path: "C:/Users/Kevin/.base-studio-code/projects/northwind/northwind-api" },
];
const SAMPLE_PROFILES = [{ id: "p1", name: "default" }, { id: "p2", name: "strict-review" }];

export function ClaudeConfigCard() {
  const allRepos = SAMPLE_REPOS;
  const [configProfiles, setConfigProfiles] = useState(SAMPLE_PROFILES);

  const [target, setTarget]                 = useState("global");
  const [instructions, setInstructions]     = useState("");
  const [allow, setAllow]                   = useState([]);
  const [deny, setDeny]                     = useState([]);
  const [allowInput, setAllowInput]         = useState("");
  const [denyInput, setDenyInput]           = useState("");

  const [activeProfileId, setActiveProfileId]   = useState(null);
  const [showSaveDialog, setShowSaveDialog]     = useState(false);
  const [newProfileName, setNewProfileName]     = useState("");

  const [reading, setReading]               = useState(false);
  const [writing, setWriting]               = useState(false);
  const [writeStatus, setWriteStatus]       = useState("idle");
  const [writeMsg, setWriteMsg]             = useState("");
  const [readTick, setReadTick]             = useState(0);

  useEffect(() => {
    setReading(true);
    setWriteStatus("idle");
    setActiveProfileId(null);
    const localPath = target === "global" ? "" : target;
    const result = invoke("read_claude_config", { localPath });
    if (result && typeof result.then === "function") {
      result.then((data) => {
        setInstructions(data.instructions);
        setAllow(data.allow);
        setDeny(data.deny);
      }).catch(() => {
        setInstructions("");
        setAllow([]);
        setDeny([]);
      }).finally(() => setReading(false));
    } else {
      setReading(false);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target, readTick]);

  function loadProfile(profile) {
    setInstructions(profile.instructions ?? "");
    setAllow(profile.tools?.allow ?? []);
    setDeny(profile.tools?.deny ?? []);
    setActiveProfileId(profile.id);
    setWriteStatus("idle");
  }

  function applyPreset(preset) {
    setAllow(preset.allow);
    setDeny(preset.deny);
  }

  function addToAllow() {
    const v = allowInput.trim();
    if (v && !allow.includes(v)) setAllow((a) => [...a, v]);
    setAllowInput("");
  }

  function addToDeny() {
    const v = denyInput.trim();
    if (v && !deny.includes(v)) setDeny((d) => [...d, v]);
    setDenyInput("");
  }

  async function handleWrite() {
    setWriting(true);
    setWriteStatus("idle");
    try {
      await invoke("write_claude_config", {
        localPath: target === "global" ? "" : target,
        instructions,
        allow,
        deny,
      });
      setWriteStatus("ok");
      setWriteMsg("Written to disk.");
    } catch (e) {
      setWriteStatus("error");
      setWriteMsg(String(e));
    } finally {
      setWriting(false);
      setTimeout(() => setWriteStatus("idle"), 4000);
    }
  }

  function handleSaveProfile() {
    const name = newProfileName.trim();
    if (!name) return;
    if (activeProfileId) {
      setConfigProfiles((ps) => ps.map((p) => p.id === activeProfileId ? { ...p, name, instructions, tools: { allow, deny } } : p));
    } else {
      const next = { id: `p${configProfiles.length + 1}`, name, instructions, tools: { allow, deny } };
      setConfigProfiles((ps) => [...ps, next]);
      setActiveProfileId(next.id);
    }
    setNewProfileName("");
    setShowSaveDialog(false);
  }

  function removeConfigProfile(id) {
    setConfigProfiles((ps) => ps.filter((p) => p.id !== id));
  }

  const targetLabel = target === "global"
    ? "global"
    : allRepos.find((r) => r.local_path === target)?.full_name ?? target;

  return (
    <Stack gap={20} style={{ maxWidth: 900 }}>
      <Box>
        <Text as="h2" mono size={16} weight={600} style={{ margin: 0 }}>
          Claude Configuration
        </Text>
        <Text as="div" tone="muted" size={12} style={{ marginTop: 4 }}>
          Edit CLAUDE.md instructions and tool permissions for each agent scope.
        </Text>
      </Box>

      <TargetSelector allRepos={allRepos} target={target} setTarget={setTarget} />

      <ProfileBar
        configProfiles={configProfiles}
        activeProfileId={activeProfileId}
        setActiveProfileId={setActiveProfileId}
        loadProfile={loadProfile}
        showSaveDialog={showSaveDialog}
        setShowSaveDialog={setShowSaveDialog}
        newProfileName={newProfileName}
        setNewProfileName={setNewProfileName}
        handleSaveProfile={handleSaveProfile}
        removeConfigProfile={removeConfigProfile}
        targetLabel={targetLabel}
      />

      <Grid cols="1fr 280px" gap={14} align="start">
        <ClaudeMdEditor
          instructions={instructions}
          setInstructions={setInstructions}
          setActiveProfileId={setActiveProfileId}
          reading={reading}
          targetLabel={targetLabel}
        />

        <ToolPermissionsPanel
          allow={allow}
          setAllow={setAllow}
          deny={deny}
          setDeny={setDeny}
          allowInput={allowInput}
          setAllowInput={setAllowInput}
          denyInput={denyInput}
          setDenyInput={setDenyInput}
          applyPreset={applyPreset}
          addToAllow={addToAllow}
          addToDeny={addToDeny}
        />
      </Grid>

      <WriteBar
        writeStatus={writeStatus}
        writeMsg={writeMsg}
        reading={reading}
        writing={writing}
        setReadTick={setReadTick}
        handleWrite={handleWrite}
      />
    </Stack>
  );
}
